function decode(word) {
  const opcode = (word >> 12) & 0xF;
  const reg = (word >> 8) & 0xF;
  const imm = word & 0xFF;
  // opcode 0001 = LOAD-IMMEDIATE already handled:
  if (opcode === 0b0001) return `LOAD R${reg}, #${imm}`;
  // TODO: 0b0010 = ADD-IMMEDIATE -> `ADD R${reg}, #${imm}`
  // TODO: 0b0011 = STORE        -> `STORE R${reg}, [${imm}]`
  return `UNKNOWN opcode ${opcode}`;
}
console.log(decode(0b0001_0010_0000_0101));
console.log(decode(0b0010_0001_0000_0011));
console.log(decode(0b0011_0001_0010_0110));
